                    HttpMessage message = _partitionsRestClient.CreateGetRequest(Guid.Parse(Id.SubscriptionId), Id.ResourceGroupName, Id.Parent.Name, Id.Name, context);
                    Response result = Pipeline.ProcessMessage(message, context);
                    Response<PartitionData> response = Response.FromValue(PartitionData.FromResponse(result), result);
                    return Response.FromValue(new PartitionResource(Client, response.Value), response.GetRawResponse());
                }
                else
                {
                    PartitionData current = Get(cancellationToken: cancellationToken).Value.Data;
                    PartitionPatch patch = new PartitionPatch();
                    foreach (KeyValuePair<string, string> tag in current.Tags)
                    {
                        patch.Tags.Add(tag);
                    }
                    patch.Tags.Remove(key);
                    Response<PartitionResource> result = Update(patch, cancellationToken: cancellationToken);
                    return Response.FromValue(result.Value, result.GetRawResponse());
                }
            }
            catch (Exception e)
            {
                scope.Failed(e);
                throw;
            }
        }
    }
}
